        "item_number": 93,
        "category": "review",
        "english": "Dating a subordinate is not a good idea.",
        "vietnamese": "Hẹn hò với một cấp dưới không phải ý hay đâu.",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "Dating a subordinate is not a good idea."
