        "category": "monologue",
        "english": "Like it or not, in this day and age, business trips are inevitable.",
        "vietnamese": "Dù thích hay là không, thời buổi này, những chuyến công tác là không thể tránh khỏi.",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "Like it or not // in this day and age // business trips are inevitable."
