        "item_number": 63,
        "category": "monologue",
        "english": "You're supposed to have conferences at some point in these kinds of trips.",
        "vietnamese": "Cậu hẳn là sẽ có mấy cái buổi hội nghị rơi vào một thời điểm nào đó trong mấy chuyến đi kiểu này.",
