        "item_number": 114,
        "category": "vocab",
        "english": "For me,... / To me,... / according to me,... / in my opinion,... / from my perspective,...",
        "vietnamese": "Với tôi,...",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "For me,... // To me,... // according to me,... // in my opinion,... // from my perspective,..."
