        "chunk_id": "chunk_erel_d2_0137",
        "item_number": 137,
        "category": "phrase",
        "english": "Come up with a new idea / Find a new idea / produce a new idea",
        "vietnamese": "Nghĩ ra một ý tưởng mới",
