        "chunk_id": "chunk_erel_d4_0046",
        "item_number": 46,
        "category": "phrase",
        "english": "Put it on hold / Suspend it / delay it / postpone it",
        "vietnamese": "Trì hoãn nó lại",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "Put it on hold // Suspend it // delay it // postpone it"
