        "item_number": 99,
        "category": "review",
        "english": "How to deal with a difficult customer?",
        "vietnamese": "Làm sao để đối phó với một khách hàng khó?",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "How to deal with a difficult customer?"
