        "item_number": 100,
        "category": "review",
        "english": "This service business is no exception either.",
        "vietnamese": "Cái ngành dịch vụnày cũng không phải là ngoại lệ.",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "This service business is no exception either."
