        "english": "What are you up to? Do you wanna have a beer?",
        "vietnamese": "Cậu đang làm gì đó? Có muốn làm ly bia không?",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "What are you up to? Do you wanna have a beer?"
