        "english": "I don't want to jinx it but that is a big if.",
        "vietnamese": "Tui không có muốn nói xui nhưng mà chuyện đó vẫn còn là một dấu hỏi lớn.",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "I don't want to jinx it but that is a big if."
