        "item_number": 92,
        "category": "review",
        "english": "I told you, we're not allowed to throw a party at the moment.",
        "vietnamese": "Tao đã bảo mày rồi, tụi mình không có được phép làm tiệc ở thời điểm này.",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "I told you // we're not allowed to throw a party at the moment."
