        "chunk_id": "chunk_erel_d8_0093",
        "item_number": 93,
        "category": "review",
        "english": "She didn't even bother to call me back!",
        "vietnamese": "Bả thậm chí còn không thèm gọi lại tui nữa mà!",
        "speaker": null,
