        "category": "sentence",
        "english": "Often, Morgan is known as a demanding boss but actually he's not a nitpicker.",
        "vietnamese": "Thông thường, Morgan được biết đến giống như là một ông sếp hay đòi hỏi nhưng thực ra ổng không phải là một kẻ hay vạch lá tìm sâu đâu.",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "Often // Morgan is known as a demanding boss but actually he's not a nitpicker."
