        "item_number": 160,
        "category": "monologue",
        "english": "No one knows what's wrong with their resume until someone points it out.",
        "vietnamese": "",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "No one knows what's wrong with their resume until someone points it out."
