        "chunk_id": "chunk_erel_d10_0161",
        "item_number": 161,
        "category": "monologue",
        "english": "Deep down, I don't think your resume is eye- catching enough.",
        "vietnamese": "Sâu bên trong, tớkhông nghĩ cái resume của cậu là đủbắt mắt đâu.",
