        "chunk_id": "chunk_erel_d10_0162",
        "item_number": 162,
        "category": "monologue",
        "english": "If you lack experience, why don't you focus on transferable skills?",
        "vietnamese": "Nếu cậu thiếu kinh nghiệm, sao cậu không tập trung vào mấy cái kỹ năng có thể chuyển đổi ấy?",
