        "chunk_id": "chunk_erel_d10_0163",
        "item_number": 163,
        "category": "monologue",
        "english": "You're a fresh graduate doesn't mean you have nothing to show. OK?",
        "vietnamese": "Cậu là một đứa mới ra trường không có nghĩa là cậu không có gì để mà \"show.\" OK?",
