        "item_number": 164,
        "category": "monologue",
        "english": "I mean you can highlight the volunteer work or the extracurricular activities or something.",
        "vietnamese": "Ý tớ là cậu có thể làm nổi bật công việc từ thiện hay mấy cái hoạt động ngoại khóa hay gì đó.",
