        "item_number": 167,
        "category": "monologue",
        "english": "Their resumes are too lengthy, you should limit it to one page.",
        "vietnamese": "Mấy cái resume của họ quá dài dòng, cậu nên giới hạn nó lại trong một trang thôi.",
