        "chunk_id": "chunk_erel_d10_0168",
        "item_number": 168,
        "category": "monologue",
        "english": "Most of our resumes are no longer scanned by human. Do you know that?",
        "vietnamese": "Hầu hết resume của bọn mình đâu có còn được scan bởi con người nữa đâu. Cậu biết cái đó không?",
