        "item_number": 169,
        "category": "monologue",
        "english": "Large companies have been using a bot called ATS to filter out underqualified candidates.",
        "vietnamese": "Mấy công ty lớn họ đều đã và đang dùng một con bot gọi là ATS để lọc ra những thí sinh không đạt chuẩn.",
