        "category": "monologue",
        "english": "Resume is a place where you demonstrate your accomplishments as well as what you have done in the past.",
        "vietnamese": "Resume là cái nơi mà cậu biểu thị những thành tích của mình cũng như những gì cậu đã làm được trong quá khứ.",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "Resume is a place where you demonstrate your accomplishments as well as what you have done in the past."
