        "chunk_id": "chunk_erel_d13_0091",
        "item_number": 91,
        "category": "dialogue",
        "english": "On condition that you will have to work for me for three years if you fail.",
        "vietnamese": "Huy: Với điều kiện rằng em sẽ phải làm việc cho anh trong ba năm nếu như em thất bại.",
        "speaker": "Huy",
        "audio_url": null,
