        "chunk_id": "chunk_erel_d13_0201",
        "item_number": 201,
        "category": "review",
        "english": "Who told you Kim dumped me back then?",
        "vietnamese": "Ai bảo cậu hồi đó con Kim nó đá tui?",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "Who told you Kim dumped me back then?"
