        "item_number": 96,
        "category": "review",
        "english": "There's a very thin line between consistency and persistence.",
        "vietnamese": "Có một lằn ranh rất mỏng giữa sự kiên định và sự lì lợm.",
        "speaker": null,
        "audio_url": null,
        "beat_prosody": "There's a very thin line between consistency and persistence."
